function normalizeIds(list) {
    const arr = Array.isArray(list) ? list : []
    const seen = new Set()
    const normalized = []

    for (const value of arr) {
        const id = Number(value)
        if (!Number.isFinite(id) || seen.has(id)) {
            continue
        }
        seen.add(id)
        normalized.push(id)
    }

    return normalized.slice(-MAX_ITEMS)
}

function loadList() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY)
        const arr = raw ? JSON.parse(raw) : []
        return normalizeIds(arr)
    } catch {
        return []
    }
}

function persistList(list) {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(normalizeIds(list)))
    } catch {
        // ignore
    }
}

function setIds(nextIds) {
        ids.value = normalizeIds(nextIds)
        persistList(ids.value)
    }

function has(productId) {
        const id = Number(productId)
        if (!Number.isFinite(id)) {
            return false
        }
        return ids.value.includes(id)
    }

function add(productId) {
        const id = Number(productId)
        if (!Number.isFinite(id) || has(id)) {
            return
        }
        setIds([...ids.value, id])
    }

function remove(productId) {
        const id = Number(productId)
        if (!Number.isFinite(id) || !has(id)) {
            return
        }
        setIds(ids.value.filter(x => x !== id))
    }

function toggle(productId) {
        if (has(productId)) {
            remove(productId)
            return
        }
        add(productId)
    }

function clear() {
        setIds([])
    }

function isAbsoluteUrl(url) {
    return /^https?:\/\//i.test(url);
}

function getBackendOrigin() {
    if (!isAbsoluteUrl(API_BASE_URL)) {
        return "";
    }
    try {
        return new URL(API_BASE_URL).origin;
    } catch {
        return "";
    }
}

function resolveBackendAssetUrl(assetPath) {
    if (!assetPath) {
        return assetPath;
    }
    if (isAbsoluteUrl(assetPath) || assetPath.startsWith("data:")) {
        return assetPath;
    }

    const normalizedPath = assetPath.startsWith("/") ?
        assetPath :
        `/${assetPath}`;
    const origin = getBackendOrigin();

    // If API base URL is relative (e.g. `/api`), rely on Vite proxy / same-origin.
    if (!origin) {
        return normalizedPath;
    }

    return `${origin}${normalizedPath}`;
}

function resolveImageUrl(imageUrl) {
    if (!imageUrl) {
        return imageUrl;
    }

    // Ensure `/images/testshoes` becomes `/images/testshoes.jpg`
    // but leave `/images/testshoes.png` or any URL with an extension as-is.
    if (typeof imageUrl === "string" && imageUrl.startsWith("/images/")) {
        const lastSegment = imageUrl.split("/").pop() || "";
        const hasExtension = /\.[a-z0-9]+$/i.test(lastSegment);
        if (!hasExtension) {
            return resolveBackendAssetUrl(`${imageUrl}.jpg`);
        }
    }

    return resolveBackendAssetUrl(imageUrl);
}

async function apiCall(endpoint, options = {}) {
    try {
        const url = `${API_BASE_URL}${endpoint}`;
        console.log(`Making ${options.method || "GET"} request to: ${url}`);
        if (options.body) {
            try {
                console.log("Request body:", JSON.parse(options.body));
            } catch {
                console.log("Request body:", options.body);
            }
        }

        const headers = {...options.headers };
        if (!(options.body instanceof FormData) && !headers["Content-Type"]) {
            headers["Content-Type"] = "application/json";
        }

        const response = await fetch(url, {
            ...options,
            headers,
        });

        let data = null;
        const contentType = response.headers.get("content-type") || "";
        const canHaveBody = response.status !== 204 && response.status !== 205;

        // 204/205 responses have no body (common for DELETE).
        if (canHaveBody) {
            const rawBody = await response.text();
            if (rawBody) {
                const isJson = contentType.indexOf("application/json") !== -1;
                if (isJson) {
                    try {
                        data = JSON.parse(rawBody);
                    } catch {
                        data = { raw: rawBody };
                    }
                } else {
                    data = { raw: rawBody };
                }
            }
        }

        console.log("Response status:", response.status);
        console.log("Response data:", data);

        if (!response.ok) {
            const errorMessage =
                data && typeof data === "object" && data.message ?
                data.message :
                `API Error: ${response.status} ${response.statusText}`;

            const error = {
                status: response.status,
                message: errorMessage,
                data,
            };

            if (data && typeof data === "object" && data.errors) {
                error.errors = data.errors;
                console.error("Validation errors:", data.errors);
            }

            throw error;
        }

        return data;
    } catch (error) {
        console.error("API Call Error:", error);
        throw error;
    }
}

