function dedupeById(list) {
        const arr = Array.isArray(list) ? list : []
        const map = new Map()
        for (const item of arr) {
            if (!item) {
                continue
            }
            const id = item.id
            if (id === null || id === undefined) {
                continue
            }
            map.set(Number(id), item)
        }
        return [...map.values()]
    }

