function loadSet () {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    const arr = raw ? JSON.parse(raw) : []
    return new Set(Array.isArray(arr) ? arr : [])
  } catch {
    return new Set()
  }
}

function persistSet (set) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify([...set]))
  } catch {
    // ignore
  }
}

function isFavorite (productId) {
    return ids.value.has(Number(productId))
  }

function toggle (productId) {
    const id = Number(productId)
    if (!Number.isFinite(id)) {
      return
    }
    const next = new Set(ids.value)
    if (next.has(id)) {
      next.delete(id)
    } else {
      next.add(id)
    }
    ids.value = next
    persistSet(ids.value)
  }

function clear () {
    ids.value = new Set()
    persistSet(ids.value)
  }

function normalizeText(value) {
    if (typeof value !== 'string') return null
    const text = value.trim()
    return text || null
}

function buildVariantCode(productCode, colorName, sizeName, existingCode = null) {
    const savedCode = normalizeText(existingCode)
    if (savedCode) return savedCode

    const parentCode = toCodePart(productCode, 'SP')
    const colorCode = toCodePart(colorName, 'MAC').slice(0, 3)
    const sizeCode = toCodePart(sizeName, 'STD')
    return `${parentCode}-${colorCode}-${sizeCode}`
}

function toVariantId(value) {
    if (value === null || value === undefined) return null

    if (typeof value === 'number') {
        return Number.isFinite(value) ? value : null
    }

    if (typeof value === 'string') {
        const text = value.trim()
        if (!text) return null
        const n = Number(text)
        return Number.isFinite(n) ? n : null
    }

    return null
}

function normalizeHexColor(value) {
    const text = normalizeText(value)
    if (!text) return null

    if (/^#[a-f\d]{3}([a-f\d]{3})?$/i.test(text)) return text
    if (/^[a-f\d]{3}([a-f\d]{3})?$/i.test(text)) return `#${text}`
    return null
}

function resolveColorMeta(input) {
    const source = input || {}
    const normalizedId = toVariantId(source.id)
    const fallback = normalizedId !== null ? FALLBACK_COLORS_BY_ID[normalizedId] : null

    const fallbackName = fallback ? fallback.name : null
    const fallbackHex = fallback ? fallback.hexCode : null

    const resolvedName =
        normalizeText(source.name) ||
        fallbackName ||
        (normalizedId !== null ? `Màu ${normalizedId}` : null)

    const resolvedHex =
        normalizeHexColor(source.hexCode) ||
        fallbackHex ||
        null

    return {
        id: normalizedId,
        name: resolvedName,
        hexCode: resolvedHex,
    }
}

function resolveSizeMeta(input) {
    const source = input || {}
    const normalizedId = toVariantId(source.id)
    const fallback = normalizedId !== null ? FALLBACK_SIZES_BY_ID[normalizedId] : null

    const resolvedName =
        normalizeText(source.name) ||
        fallback ||
        (normalizedId !== null ? `Size ${normalizedId}` : null)

    return {
        id: normalizedId,
        name: resolvedName,
    }
}

