function buildProductCatalog(products) {
    if (!Array.isArray(products) || products.length === 0) {
        return "Chưa có sản phẩm nào trong hệ thống.";
    }

    const catalog = products.map((p) => ({
        id: p.id,
        name: p.name || "Không tên",
        price: p._minPrice || p.price || p.minPrice || 0,
        brand: p.brandName || p.brand || "",
        category: p.categoryName || p.category || "",
        description: p.description || "",
    }));

    return JSON.stringify(catalog, null, 0);
}

function parseGeminiResponse(text) {
    const cleaned = text
        .replace(/```json\s*/gi, "")
        .replace(/```\s*/g, "")
        .trim();

    try {
        const parsed = JSON.parse(cleaned);
        return {
            message: String(parsed.message || parsed.text || parsed.reply || ""),
            productIds: Array.isArray(parsed.productIds) ?
                parsed.productIds.map(Number).filter(Number.isFinite) : [],
        };
    } catch {
        // Gemini sometimes returns plain text instead of JSON
        return {
            message: text.trim(),
            productIds: [],
        };
    }
}

function isGeminiConfigured() {
    return !!GEMINI_API_KEY && GEMINI_API_KEY !== "your_gemini_api_key_here";
}

function initGemini() {
    if (!isGeminiConfigured()) {
        console.warn("[Gemini] API key chưa được cấu hình. Thêm VITE_GEMINI_API_KEY vào file .env");
        return false;
    }

    try {
        genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
        chatSession = null;
        return true;
    } catch (err) {
        console.error("[Gemini] Khởi tạo thất bại:", err);
        return false;
    }
}

async function sendChatMessage(userMessage, products = []) {
    if (!genAI) {
        const ok = initGemini();
        if (!ok) {
            return {
                message: "Trợ lý AI chưa được kích hoạt. Vui lòng liên hệ quản trị viên.",
                productIds: [],
            };
        }
    }

    try {
        const model = genAI.getGenerativeModel({
            model: "gemini-3.5-flash",
            generationConfig: {
                temperature: 0.7,
                topP: 0.9,
                maxOutputTokens: 1024,
            },
        });

        if (!chatSession) {
            const catalog = buildProductCatalog(products);
            chatSession = model.startChat({
                history: [{
                        role: "user",
                        parts: [{
                            text: `${SYSTEM_PROMPT}\n\nDanh sách sản phẩm hiện có:\n${catalog}`,
                        }, ],
                    },
                    {
                        role: "model",
                        parts: [{
                            text: '{"message": "Xin chào! Tôi có thể giúp bạn tìm áo thể thao phù hợp với phong cách, ngân sách và kích cỡ của bạn. Bạn đang muốn tìm sản phẩm nào?", "productIds": []}',
                        }, ],
                    },
                ],
            });
        }

        const result = await chatSession.sendMessage(userMessage);
        const responseText = result.response.text();

        return parseGeminiResponse(responseText);
    } catch (err) {
        console.error("[Gemini] Lỗi gửi tin nhắn:", err);

        // Reset session on error so next message starts fresh
        chatSession = null;

        var errorMessage = err && err.message ? err.message : "";

        if (errorMessage.indexOf("SAFETY") !== -1) {
            return {
                message: "Xin lỗi, tôi không thể trả lời câu hỏi này. Bạn có thể hỏi về sản phẩm áo thể thao hoặc nhu cầu mua sắm của mình nhé!",
                productIds: [],
            };
        }

        return {
            message: "Xin lỗi, tôi đang gặp sự cố. Vui lòng thử lại sau nhé!",
            productIds: [],
        };
    }
}

function resetChat() {
    chatSession = null;
}

function firstDefined(values) {
    for (const value of values) {
        if (value !== null && value !== undefined) {
            return value
        }
    }
    return null
}

function normalizeCode(value) {
    if (value === null || value === undefined) {
        return ''
    }
    const code = String(value).trim()
    return code
}

function toFiniteNumber(value) {
    if (value === null || value === undefined) {
        return null
    }
    const n = Number(value)
    return Number.isFinite(n) ? n : null
}

function normalizeAppliedVoucher(rawVoucher, fallbackCode = '') {
    const source = rawVoucher && typeof rawVoucher === 'object' ? rawVoucher : {}
    const nested = source.voucher && typeof source.voucher === 'object' ? source.voucher : {}

    const normalizedCode = normalizeCode(
        firstDefined([
            source.code,
            source.voucherCode,
            source.voucher_code,
            nested.code,
            fallbackCode,
        ]),
    )

    const voucherId = toFiniteNumber(
        firstDefined([
            source.voucherId,
            source.voucher_id,
            source.id,
            nested.id,
        ]),
    )

    const discountType = normalizeCode(
        firstDefined([
            source.discountType,
            source.discount_type,
            nested.discountType,
            nested.discount_type,
        ]),
    )

    const discountValue = Math.max(
        0,
        toFiniteNumber(
            firstDefined([
                source.discountValue,
                source.discount_value,
                nested.discountValue,
                nested.discount_value,
            ]),
        ) || 0,
    )

    const discountAmount = Math.max(
        0,
        toFiniteNumber(
            firstDefined([
                source.discountAmount,
                source.discount_amount,
                source.amount,
                source.value,
                nested.discountAmount,
                nested.discount_amount,
            ]),
        ) || 0,
    )

    const minOrderValue = Math.max(
        0,
        toFiniteNumber(
            firstDefined([
                source.minOrderValue,
                source.min_order_value,
                nested.minOrderValue,
                nested.min_order_value,
            ]),
        ) || 0,
    )

    return {
        id: voucherId,
        code: normalizedCode,
        discountType,
        discountValue,
        discountAmount,
        minOrderValue,
        raw: source,
    }
}
